public class DuplicateCodeException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public DuplicateCodeException(String code, Throwable cause) {
        super("이미 등록된 코드입니다: " + code, cause);
    }
}

package com.ssafy.sample.util;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

/**
 * 제공 코드입니다. 수정하지 않습니다.
 * 수업 기본 계정(ssafy/ssafy)과 로컬 MySQL 포트를 기준으로 연결합니다.
 */
public class DBUtil {
    private static final String DRIVER = "com.mysql.cj.jdbc.Driver";
    private static final String URL = "jdbc:mysql://127.0.0.1:3306/ssafy_book?serverTimezone=UTC&characterEncoding=UTF-8";
    private static final String USER = "ssafy";
    private static final String PASSWORD = "ssafy";

    static {
        try {
            Class.forName(DRIVER);
        } catch (ClassNotFoundException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    public static Connection getConnection() throws SQLException {
        return DriverManager.getConnection(URL, USER, PASSWORD);
    }

    public static void close(AutoCloseable... closeables) {
        for (AutoCloseable c : closeables) {
            if (c != null) {
                try {
                    c.close();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

-- 학습용 데이터베이스입니다. 실행하면 기존 ssafy_book 데이터베이스의 두 테이블이 초기화됩니다.
CREATE DATABASE IF NOT EXISTS ssafy_book DEFAULT CHARACTER SET utf8mb4;
USE ssafy_book;

DROP TABLE IF EXISTS book;
DROP TABLE IF EXISTS member;

-- 로그인과 세션 사용자 식별에 쓰는 회원 테이블
CREATE TABLE member (
    mno INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(30) NOT NULL,
    email VARCHAR(50) NOT NULL UNIQUE,
    password VARCHAR(50) NOT NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'USER'
);

